/* --- 2. 全局信纸背景与重置 (恢复圆角 + 页面微拉宽) --- */
.xt-root {
    --xt-bg: #fdfdfd !important;
    font-family: 'ZCOOL KuaiLe', "Chalkboard SE", "Comic Sans MS", cursive, sans-serif !important;
    padding: 0 !important;
    margin: 0 -4px !important; /* 微调页面拉宽，更舒展 */
    width: calc(100% + 8px) !important;

    background-color: var(--xt-bg) !important;
    border-radius: 12px !important; /* 恢复好看的手账圆角 */
    box-shadow: 0 4px 20px rgba(0,0,0,0.06) !important; 

    /* 铺满全屏的虚线信纸背景，严格 40px 一行 */
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg%20width%3D%27100%25%27%20height%3D%2740%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Cline%20x1%3D%270%27%20y1%3D%2739%27%20x2%3D%272000%27%20y2%3D%2739%27%20stroke%3D%27%23d0d0d0%27%20stroke-width%3D%271.5%27%20stroke-dasharray%3D%278%,6%27%2F%3E%3C%2Fsvg%3E") !important;
    background-size: 100% 40px !important;

    /* 【神级对齐】11px偏移量，完美托住汉字的底部基线！ */
    background-position: 0 11px !important; 
