.xt-text { background: transparent !important; border: none !important; margin: 0 !important; font-style: normal !important; display: block !important; }

/* --- 3. 顶栏伪装工具条 (固定 50px 高度，带纯实线底部边界) --- */
.xt-text-sysToolbar {
    height: 50px !important; 
    box-sizing: border-box !important;
    background-color: #fdfdfd !important;
    /* 高亮的纯实线边界，利用 z-index 压住底层背景 */
    border-bottom: 1.5px solid #c8c8c8 !important; 
