@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;700&display=swap');

.xt-root {
  --xt-bg: #0a0a0e;
  --xt-text: #e8e0f0;
  --xt-text-sub: #9a8aaa;
  --xt-text-muted: #4a4a5e;
  --xt-accent: #b0a8d8;
  --xt-accent-bg: rgba(168, 160, 208, 0.08);
  --xt-border: rgba(168, 160, 208, 0.1);
  --xt-radius: 18px;
  --xt-font: 'Noto Serif SC', serif;

  width: 100%;
  max-width: 420px;
  height: 660px;
  max-height: 85vh;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--xt-bg);
  border: 1px solid #1a1a2a;
  border-radius: var(--xt-radius);
  padding: 0 !important;
  margin: 0 auto;
  scrollbar-width: thin;
  scrollbar-color: #3a2a5a transparent;
  position: relative;
}

.xt-root::-webkit-scrollbar {
  width: 3px;
}
.xt-root::-webkit-scrollbar-track {
  background: transparent;
}
.xt-root::-webkit-scrollbar-thumb {
  background: #3a2a5a;
  border-radius: 10px;
}

.xt-image {
  display: none !important;
}

/* ===== 背景图 - 固定不动 ===== */
.xt-root::before {
  content: '';
  display: block;
  width: 100%;
  height: 200px;
  background-image: url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEWPN5qQNN7YPu2UAXytEc7eRu0KNQgBwAC_R8AAq3jCFZl34BdvK1WAzwE.jpg');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  flex-shrink: 0;
  position: sticky;
  top: 0;
  z-index: 0;
}

.xt-content {
  padding: 0 16px 16px 16px;
  margin-top: 0;
  position: relative;
  z-index: 5;
  background: #0a0a0e;
  border-radius: 24px 24px 0 0;
  padding-bottom: 0;
  margin-top: -12px;
  overflow-x: hidden !important;
  min-height: 400px;
}

.xt-section-title {
  font-size: 12px !important;
  letter-spacing: 2px !important;
  font-weight: 600 !important;
  margin-top: 14px !important;
  margin-bottom: 4px !important;
}

.xt-section-title:nth-of-type(1) { color: #b0a0d8 !important; }
.xt-section-title:nth-of-type(2) { color: #b0a0d8 !important; }
.xt-section-title:nth-of-type(3) { color: #f0a050 !important; font-size: 13px !important; }
.xt-section-title:nth-of-type(4) { color: #a8e6cf !important; }
.xt-section-title:nth-of-type(5) { color: #b0a0d8 !important; }
.xt-section-title:nth-of-type(6) { color: #b0a0d8 !important; }

.xt-section-body {
  background: rgba(255, 255, 255, 0.02);
  border-left: 2px solid #3a2a5a;
  color: #d0cce0;
  font-size: 14px;
  line-height: 1.8;
  padding: 10px 14px;
  border-radius: 0 8px 8px 0;
}

.xt-collapse {
  margin-top: 12px;
  border: 1px solid rgba(168, 160, 208, 0.06);
  border-radius: 8px;
  overflow: hidden;
}

.xt-collapse-1 {
  margin-top: 12px !important;
}

.xt-collapse-header {
  background: rgba(168, 160, 208, 0.03);
  padding: 10px 14px;
  color: #b0a0d8;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}

.xt-collapse-arrow {
  color: #5a4a7a;
  font-size: 12px;
  transition: transform 0.3s ease;
  display: inline-block;
}

.xt-collapse-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
  padding: 0 14px;
}

.xt-collapse.open .xt-collapse-body {
  max-height: 2000px;
  padding: 10px 14px 14px 14px;
}

