/* --- 4. 日记正文排版 (严格 40px 行高，严丝合缝) --- */
.xt-text-diaryTitle {
    font-size: 24px !important; color: #333 !important; text-align: center !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 10px 0 0 0 !important; padding: 0 !important;
    letter-spacing: 4px !important; 
}

.xt-text-diaryContent {
    font-size: 20px !important; color: #222 !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 0 !important; padding: 0 16px !important;
    text-indent: 1.5em !important;
    white-space: pre-wrap !important; letter-spacing: 2px !important;
}

.xt-text-diaryEnding {
    font-size: 20px !important; color: #222 !important; text-align: right !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 0 !important; padding: 0 40px 0 0 !important;
}

/* --- 5. 米字格颜文字区域 (单行锁死防断线 + 稳压底色) --- */
.xt-text-kaomoji {
    display: flex !important; justify-content: center !important; align-items: center !important;
    width: 160px !important; height: 160px !important;

    /* 往下刚好空出 2 行虚线（2 x 40 = 80px）并推到右下角 */
    margin-top: 80px !important; 
    margin-left: auto !important; 
    margin-right: 24px !important;
    margin-bottom: 40px !important;

    /* 【单行锁死防错位】强制单行显示，多出部分隐藏，绝不挤坏网格 */
    font-size: 22px !important; color: #555 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    padding: 0 8px !important;
    box-sizing: border-box !important;

    /* 强力叠加：底层白色遮盖全局虚线，上层画出不会丢失的 SVG 十字虚线网格 */
    background: #fdfdfd url("data:image/svg+xml;base64,") no-repeat center center / contain !important;
}
